31	async function runLocalComputerUse(context: RuntimeWorkerContext<LocalComputerUsePayload>) {
32	  const { taskId, workerRunId } = context;
33	  const { taskGoal, modelConfig, settings, visionEnabled } = context.payload;
34	
35	  try {
36	    let agent: ComputerUseAgent | VisionComputerUseAgent;
37	    const useNativeOperator = process.platform === 'win32';
38	    const operator = useNativeOperator ? createWindowsOperator() : undefined;
39	
40	    if (visionEnabled && settings?.vision_api_key) {
41	      const visionModelConfig = buildVisionModelConfig(settings);
42	      agent = createVisionComputerUseAgent({ model: modelConfig, visionModel: visionModelConfig, operator, maxSteps: 50 });
43	      recordRuntimeEvent({ taskId, type: 'step', payload: { step: { type: 'think', content: `Vision ComputerUse agent initialized with dedicated vision model and ${useNativeOperator ? 'native Windows' : 'mock'} operator, starting task...`, timestamp: Date.now() } } });
44	    } else {
45	      agent = createComputerUseAgent({ model: modelConfig, operator, maxSteps: 50, config: { enableVision: !!modelConfig.supportsVision } });
46	      recordRuntimeEvent({ taskId, type: 'step', payload: { step: { type: 'think', content: `ComputerUse agent initialized with ${useNativeOperator ? 'native Windows' : 'mock'} operator, starting task...`, timestamp: Date.now() } } });
47	    }
48	
49	    activeComputerUseAgents.set(taskId, agent);
50	    await agent.initialize();
51	    context.heartbeat();
52	
53	    const task = await agent.executeTask(taskGoal);
54	    context.heartbeat();
55	    const steps = task.steps.map(s => ({
56	      type: s.type,
57	      content: s.content,
58	      action: s.action,
59	      timestamp: s.timestamp
60	    }));
61	
62	    for (const step of steps) {
63	      if (context.isCancelled()) return;
64	      recordRuntimeEvent({ taskId, type: 'step', payload: { step } });
65	    }
66	
67	    updateRuntimeTask(taskId, { status: task.status as any, result: task.result || '', error: task.error || '' });
68	    completeWorkerRun(workerRunId, task.status as any, task.error || undefined);
69	    runExec(`UPDATE agent_tasks SET status = ?, result = ?, steps = ?, completed_at = ? WHERE id = ?`, [task.status, task.result || '', JSON.stringify(steps), Date.now(), taskId]);
70	    recordRuntimeEvent({ taskId, type: 'task_complete', payload: { taskId, status: task.status, result: task.result, error: task.error, steps } });
71	  } catch (error: any) {
72	    console.error('[LocalComputerUseAdapter] Execution error:', error);
73	    const message = error.message || 'Unknown error';
74	    updateRuntimeTask(taskId, { status: 'failed', error: message });
75	    completeWorkerRun(workerRunId, 'failed', message);
76	    runExec(`UPDATE agent_tasks SET status = ?, error = ?, completed_at = ? WHERE id = ?`, ['failed', message, Date.now(), taskId]);
77	    recordRuntimeEvent({ taskId, type: 'task_error', payload: { taskId, error: message } });
78	  } finally {
79	    activeComputerUseAgents.delete(taskId);
80	  }
81	}
