62	// ============================================
63	// OxygenClaw Agent
64	// ============================================
65	export class OxygenAgent {
66	  private id: string;
67	  private config: AgentConfig;
68	  private memory: OMMManager;
69	  private cognition: ODCEngine;
70	  private mcpManager: MCPClientManager;
71	  private containerManager: ContainerManager;
72	  private modelRegistry: ModelRegistry;
73	  private currentTask?: AgentTask;
74	  private webSearchCount = 0;
75	  private switchEvents: ModelSwitchEvent[] = [];
76	  private mcpToolWrappers: Map<string, MCPToolWrapper> = new Map();
77	  private moaCoordinator?: MoACoordination;
78	  private cancelled = false;
79	
80	  constructor(config: AgentConfig) {
81	    this.id = uuidv4();
82	    this.config = config;
83	    this.memory = createMemoryManager();
84	    this.cognition = createODCEngine(config.mode, config.interactionMode || 'task');
85	    this.mcpManager = new MCPClientManager();
86	    this.containerManager = new ContainerManager();
87	    this.modelRegistry = config.modelRegistry || createModelRegistry();
88	  }
89	
90	  /**
91	   * Initialize the agent
92	   */
93	  async initialize(): Promise<void> {
94	    for (const server of this.config.mcpServers) {
95	      await this.mcpManager.register(server);
96	      await this.mcpManager.connect(server.id);
97	
98	      const client = this.mcpManager.getClient(server.id);
99	      if (client && client.isConnected()) {
100	        const wrapper = new MCPToolWrapper(client);
101	        await wrapper.refreshTools();
102	        this.mcpToolWrappers.set(server.id, wrapper);
103	      }
104	    }
105	
106	    if (this.config.enableContainers) {
107	      await this.containerManager.createAgentContainer({
108	        image: 'oxygen-claw/agent:latest'
109	      });
110	    }
111	
112	    if (!this.modelRegistry.getModel(this.config.model.id)) {
113	      this.modelRegistry.registerModel(this.config.model);
114	    }
115	    this.modelRegistry.switchModel({ modelName: this.config.model.name });
116	
117	    const modeConfig = MODE_CONFIGS[this.config.mode];
118	    if (modeConfig.task.enableMoA) {
119	      await this.initializeMoACoordinator();
120	    }
121	
122	    this.memory.store(
123	      `Agent ${this.id} initialized in ${this.config.mode} mode with model ${this.config.model.name}`,
124	      ['init', this.config.mode, 'model'],
125	      []
126	    );
127	  }
