129	  /**
130	   * Initialize MoA coordinator for task mode
131	   */
132	  private async initializeMoACoordinator(): Promise<void> {
133	    const modeConfig = MODE_CONFIGS[this.config.mode];
134	    const taskConfig = modeConfig.task;
135	    const availableModels = this.modelRegistry.listModels();
136	
137	    const reasoningModels = availableModels.filter(m => 
138	      m.supportsTools && m.maxTokens >= 32000
139	    );
140	    
141	    const fastModels = availableModels.filter(m => 
142	      m.maxTokens >= 8000 && m.costPer1KInput < 0.001
143	    );
144	
145	    const coordinatorModel = reasoningModels.length > 0 
146	      ? reasoningModels[0] 
147	      : this.config.model;
148	
149	    this.moaCoordinator = {
150	      strategy: taskConfig.maxAgents > 2 ? 'parallel' : 'sequential',
151	      agents: [],
152	      coordinatorModel
153	    };
154	  }
