156	  /**
157	   * Switch model by standard name or alias
158	   */
159	  async switchModel(modelName: string): Promise<{
160	    success: boolean;
161	    model?: ModelConfig;
162	    error?: string;
163	    previousModel?: ModelConfig;
164	  }> {
165	    const previousModel = this.modelRegistry.getActiveModel();
166	    const normalizedName = normalizeModelName(modelName);
167	
168	    const options: ModelSwitchOptions = {
169	      modelName: normalizedName,
170	      preserveContext: true,
171	      migrateMemory: true
172	    };
173	
174	    const result = this.modelRegistry.switchModel(options);
175	
176	    if (result) {
177	      this.switchEvents.push({
178	        fromModelId: previousModel?.id || '',
179	        fromModelName: previousModel?.name || 'none',
180	        toModelId: result.id,
181	        toModelName: result.name,
182	        reason: `Switched to ${normalizedName}`,
183	        timestamp: new Date(),
184	        taskId: this.currentTask?.id
185	      });
186	
187	      this.config.model = result;
188	
189	      if (this.currentTask) {
190	        this.addStep(this.currentTask, 'model_switch', 
191	          `Switched from ${previousModel?.displayName || 'none'} to ${result.displayName}`);
192	      }
193	
194	      this.memory.store(
195	        `Model switched to ${result.displayName} (${result.name})`,
196	        ['model', 'switch', result.provider.toLowerCase()],
197	        []
198	      );
199	
200	      const modeConfig2 = MODE_CONFIGS[this.config.mode];
201	      if (modeConfig2.task.enableMoA) {
202	        await this.updateMoACoordinatorModel(result);
203	      }
204	
205	      return {
206	        success: true,
207	        model: result,
208	        previousModel: previousModel || undefined
209	      };
210	    }
211	
212	    const suggestions = suggestModelNames(modelName);
213	
214	    return {
215	      success: false,
216	      error: `Model "${modelName}" not found. Did you mean: ${suggestions.join(', ')}?`
217	    };
218	  }
