264	  /**
265	   * Execute a task with current model
266	   */
267	  async executeTask(prompt: string): Promise<AgentTask> {
268	    const modeConfig = MODE_CONFIGS[this.config.mode];
269	    const activeConfig = this.config.interactionMode === 'chat' ? modeConfig.chat : modeConfig.task;
270	    const currentModel = this.getCurrentModel();
271	
272	    const task: AgentTask = {
273	      id: uuidv4(),
274	      prompt,
275	      mode: this.config.mode,
276	      interactionMode: this.config.interactionMode,
277	      modelId: currentModel?.id || this.config.model.id,
278	      modelName: currentModel?.displayName || this.config.model.displayName,
279	      status: 'running',
280	      createdAt: new Date(),
281	      steps: [],
282	      webSearchesUsed: 0
283	    };
284	
285	    this.currentTask = task;
286	    this.webSearchCount = 0;
287	    this.cancelled = false;
288	
289	    try {
290	      // Store task in memory with model info
291	      this.memory.store(
292	        `Task [${task.mode}]: ${prompt} (Model: ${task.modelName})`,
293	        ['task', this.config.mode, 'model', task.modelId],
294	        [task.id]
295	      );
296	
297	      // Execute cognition loop
298	      await this.runCognitionLoop(task);
299	
300	      task.status = 'completed';
301	      task.completedAt = new Date();
302	    } catch (error) {
303	      task.status = 'failed';
304	      task.error = String(error);
305	      task.completedAt = new Date();
306	    }
307	
308	    return task;
309	  }
