311	  /**
312	   * Run cognition loop
313	   */
314	  private async runCognitionLoop(task: AgentTask): Promise<void> {
315	    const modeConfig = MODE_CONFIGS[task.mode];
316	    const activeConfig = task.interactionMode === 'chat' ? modeConfig.chat : modeConfig.task;
317	    let context: any = { 
318	      task: task.prompt, 
319	      mode: task.mode,
320	      interactionMode: task.interactionMode,
321	      model: task.modelName
322	    };
323	
324	    while (task.status === 'running' && !this.cancelled) {
325	      // Check web search limit (-1 means unlimited)
326	      if (activeConfig.maxWebSearches !== -1 && this.webSearchCount >= activeConfig.maxWebSearches) {
327	        await this.addStep(task, 'output', 'Web search limit reached, proceeding with available information');
328	        break;
329	      }
330	
331	      // Run ODC cognition
332	      const result = await this.cognition.think(
333	        task.prompt,
334	        context,
335	        this.getAvailableTools()
336	      );
337	
338	      await this.addStep(task, 'think', `[${result.level}] ${result.reasoning}`);
339	
340	      // Execute based on next action
341	      switch (result.nextAction) {
342	        case 'search':
343	          if (activeConfig.maxWebSearches === -1 || this.webSearchCount < activeConfig.maxWebSearches) {
344	            await this.performWebSearch(task);
345	            this.webSearchCount++;
346	          }
347	          break;
348	
349	        case 'tool':
350	          await this.executeTools(task);
351	          break;
352	
353	        case 'delegate':
354	          await this.delegateToAgents(task, result.agentsToSpawn || 1);
355	          break;
356	
357	        case 'output':
358	          await this.generateOutput(task);
359	          break;
360	
361	        default:
362	          await this.generateOutput(task);
363	      }
364	
365	      // Update context
366	      (context as any).reasoning = this.cognition.getReasoningHistory().join('\n');
367	    }
368	
369	    if (this.cancelled) {
370	      task.status = 'failed';
371	      task.error = 'Task cancelled by user';
372	      await this.addStep(task, 'output', 'Task cancelled by user');
373	    }
374	  }
