376	  /**
377	   * Perform web search
378	   */
379	  private async performWebSearch(task: AgentTask): Promise<void> {
380	    await this.addStep(task, 'search', `Searching: "${task.prompt}"`);
381	    try {
382	      const results = await webSearch(task.prompt);
383	      if (results.length === 0) {
384	        await this.addStep(task, 'search', 'No results found.');
385	        return;
386	      }
387	      const summary = results.slice(0, 5).map((r, i) => `${i + 1}. [${r.title}](${r.url})\n   ${r.snippet}`).join('\n\n');
388	      await this.addStep(task, 'search', summary);
389	      task.searchResults = (task.searchResults || []).concat(results);
390	    } catch (err: any) {
391	      await this.addStep(task, 'search', `Search failed: ${err.message || String(err)}`);
392	    }
393	  }
