395	  /**
396	   * Execute available tools via MCP
397	   */
398	  private async executeTools(task: AgentTask): Promise<void> {
399	    const tools = await this.getMCPTools();
400	    if (tools.length === 0) {
401	      await this.addStep(task, 'tool', 'No MCP tools available');
402	      return;
403	    }
