73	  enqueue(job: RuntimeJob) {
74	    if (!this.adapters.has(job.workerType)) {
75	      throw new Error(`Worker adapter not registered: ${job.workerType}`);
76	    }
77	
78	    this.queue.push(job);
79	    recordRuntimeEvent({
80	      taskId: job.taskId,
81	      type: 'task_queued',
82	      payload: { taskId: job.taskId, status: 'pending', workerType: job.workerType, queueSize: this.queue.length }
