89	    if (queuedIndex >= 0) {
90	      const [job] = this.queue.splice(queuedIndex, 1);
91	      updateRuntimeTask(taskId, { status: 'cancelled' });
92	      completeWorkerRun(job.workerRunId, 'cancelled', 'Cancelled before start');
93	      recordRuntimeEvent({ taskId, type: 'task_cancelled', payload: { taskId, status: 'cancelled', cancelledAt: Date.now() } });
