226	      updateRuntimeTask(job.taskId, { status: 'failed', error: message });
227	      completeWorkerRun(job.workerRunId, 'failed', message);
228	      recordRuntimeEvent({ taskId: job.taskId, type: 'task_error', payload: { taskId: job.taskId, error: message, status: 'failed' } });
229	    }).finally(() => {
