400	/**
401	 * Run a SELECT query and return all rows as plain objects.
402	 * Signature-compatible with the previous sql.js implementation.
403	 */
404	export function runQuery(sql: string, params: any[] = []): any[] {
405	  const database = getDB();
406	  const stmt = database.prepare(sql);
407	  return stmt.all(...normalizeParams(params));
408	}
409	
410	/**
411	 * Run a write statement (INSERT/UPDATE/DELETE/DDL).
412	 * Signature-compatible with the previous sql.js implementation.
413	 * Unlike sql.js, better-sqlite3 writes straight to disk — no manual flush.
414	 */
415	export function runExec(sql: string, params: any[] = []): void {
416	  const database = getDB();
417	  database.prepare(sql).run(...normalizeParams(params));
418	}
419	
420	/**
421	 * Run an INSERT and return the last inserted rowid.
422	 * Signature-compatible with the previous sql.js implementation.
423	 */
424	export function runInsert(sql: string, params: any[] = []): number {
425	  const database = getDB();
426	  const info = database.prepare(sql).run(...normalizeParams(params));
427	  return Number(info.lastInsertRowid) || 0;
428	}
