430	/**
431	 * Run a function inside a synchronous transaction. All writes commit
432	 * atomically, or roll back together on throw. Used to make multi-statement
433	 * operations (e.g. event seq allocation) race-free.
434	 */
435	export function runTransaction<T>(fn: () => T): T {
436	  const database = getDB();
437	  return database.transaction(fn)();
438	}
