442	 * is a no-op. A checkpoint is issued to flush the WAL to the main db file.
443	 */
444	export function persistDB(): void {
445	  if (!db) return;
446	  try {
447	    db.pragma('wal_checkpoint(PASSIVE)');
448	  } catch (err) {
449	    console.error('Failed to checkpoint database:', err);
450	  }
451	}
