192	  supportsTools: boolean;
193	
194	  constructor(providerName: string) {
195	    const impl = PROVIDER_IMPLEMENTATIONS[providerName.toLowerCase()] || PROVIDER_IMPLEMENTATIONS.openai;
196	    this.name = providerName;
197	    this.baseUrl = impl.baseUrl;
198	    this.apiKeyEnv = impl.apiKeyEnv;
