203	  async generate(
204	    model: ModelConfig,
205	    messages: Array<{ role: string; content: any }>,
206	    options?: {
207	      temperature?: number;
208	      maxTokens?: number;
209	      tools?: any[];
210	      toolChoice?: string | { type: string; function: { name: string } };
211	    }
212	  ): Promise<LLMResponse> {
213	    const startTime = Date.now();
214	    const apiKey = model.apiKey || process.env[this.apiKeyEnv] || '';
215	    const url = `${model.baseUrl || this.baseUrl}/chat/completions`;
216	
217	    const body: Record<string, unknown> = {
218	      model: model.name,
219	      messages: messages,
220	      temperature: options?.temperature || 0.7,
221	      max_tokens: options?.maxTokens || model.maxTokens
222	    };
223	
224	    if (options?.tools && options.tools.length > 0) {
225	      body.tools = options.tools;
226	      if (options.toolChoice) {
227	        body.tool_choice = options.toolChoice;
228	      }
229	    }
230	
231	    const response = await fetch(url, {
232	      method: 'POST',
233	      headers: {
234	        'Content-Type': 'application/json',
235	        'Authorization': `Bearer ${apiKey}`
236	      },
237	      body: JSON.stringify(body)
238	    });
239	
240	    if (!response.ok) {
241	      const errorText = await response.text();
242	      throw new Error(`LLM API error: ${response.status} - ${errorText}`);
243	    }
244	
245	    const data = await response.json() as {
246	      choices?: Array<{ message?: { content: string }; finish_reason?: string }>;
247	      usage?: { prompt_tokens?: number; completion_tokens?: number; total_tokens?: number };
248	      content?: Array<{ text?: string }>;
249	      candidates?: Array<{ content?: { parts?: Array<{ text?: string }> } }>;
250	      result?: string;
251	    };
252	    const latency = Date.now() - startTime;
253	
254	    const impl = PROVIDER_IMPLEMENTATIONS[model.provider.toLowerCase()] || PROVIDER_IMPLEMENTATIONS.openai;
255	    
256	    return {
257	      content: impl.extractContent(data),
258	      model: model.name,
259	      usage: {
260	        promptTokens: data.usage?.prompt_tokens || 0,
261	        completionTokens: data.usage?.completion_tokens || 0,
262	        totalTokens: data.usage?.total_tokens || 0
263	      },
264	      latency,
265	      finishReason: data.choices?.[0]?.finish_reason
266	    };
267	  }
