269	  async *stream(
270	    model: ModelConfig,
271	    messages: Array<{ role: string; content: any }>,
272	    options?: {
273	      temperature?: number;
274	      maxTokens?: number;
275	      tools?: any[];
276	    }
277	  ): AsyncGenerator<LLMStreamChunk> {
278	    const apiKey = model.apiKey || process.env[this.apiKeyEnv] || '';
279	    const url = `${model.baseUrl || this.baseUrl}/chat/completions`;
280	
281	    const body: Record<string, unknown> = {
282	      model: model.name,
283	      messages: messages,
284	      temperature: options?.temperature || 0.7,
285	      max_tokens: options?.maxTokens || model.maxTokens,
286	      stream: true
287	    };
288	
289	    if (options?.tools && options.tools.length > 0) {
290	      body.tools = options.tools;
291	    }
292	
293	    const response = await fetch(url, {
294	      method: 'POST',
295	      headers: {
296	        'Content-Type': 'application/json',
297	        'Authorization': `Bearer ${apiKey}`
298	      },
299	      body: JSON.stringify(body)
300	    });
301	
302	    if (!response.ok) {
303	      const errorText = await response.text();
304	      throw new Error(`LLM API error: ${response.status} - ${errorText}`);
305	    }
306	
307	    const reader = response.body?.getReader();
308	    if (!reader) {
309	      throw new Error('Failed to get response reader');
310	    }
311	
312	    const decoder = new TextDecoder();
313	    const impl = PROVIDER_IMPLEMENTATIONS[model.provider.toLowerCase()] || PROVIDER_IMPLEMENTATIONS.openai;
314	
315	    while (true) {
316	      const { done, value } = await reader.read();
317	      if (done) break;
318	
319	      const text = decoder.decode(value);
320	      const lines = text.split('\n').filter(line => line.trim() !== '');
321	
322	      for (const line of lines) {
323	        if (line.startsWith('data: ')) {
324	          const jsonStr = line.slice(6);
325	          if (jsonStr === '[DONE]') {
326	            yield { content: '', done: true };
327	            return;
328	          }
329	          try {
330	            const data = JSON.parse(jsonStr);
331	            const content = impl.extractStreamContent(data);
332	            if (content) {
333	              yield { content, done: false };
334	            }
335	          } catch {
336	            continue;
337	          }
338	        }
339	      }
340	    }
341	
342	    yield { content: '', done: true };
343	  }
344	}
