364	export async function callLLM(
365	  model: ModelConfig,
366	  messages: Array<{ role: string; content: any }>,
367	  options?: {
368	    temperature?: number;
369	    maxTokens?: number;
370	    tools?: any[];
371	    toolChoice?: string | { type: string; function: { name: string } };
372	    streaming?: boolean;
373	    onChunk?: (chunk: LLMStreamChunk) => void;
374	  }
375	): Promise<LLMResponse> {
376	  const provider = LLMProviderFactory.create(model.provider);
377	  
378	  if (options?.streaming && provider.supportsStreaming && options.onChunk) {
379	    const startTime = Date.now();
380	    let fullContent = '';
381	    for await (const chunk of provider.stream(model, messages, options)) {
382	      fullContent += chunk.content;
383	      options.onChunk(chunk);
384	      if (chunk.done) break;
385	    }
386	    
387	    return {
388	      content: fullContent,
389	      model: model.name,
390	      usage: {
391	        promptTokens: 0,
392	        completionTokens: 0,
393	        totalTokens: 0
394	      },
395	      latency: Date.now() - startTime
396	    };
397	  }
398	
399	  return provider.generate(model, messages, options);
400	}
