101	export function recordRuntimeEvent(input: RuntimeEventInput) {
102	  const id = uuidv4();
103	  const now = Date.now();
104	
105	  // Allocate seq and insert atomically. Previously "SELECT MAX(seq)+1" and the
106	  // INSERT were two separate statements, so two concurrent events could read the
107	  // same MAX and collide on seq — breaking ordering and afterSeq incremental
108	  // fetch. A synchronous transaction serializes allocation; the UNIQUE index on
109	  // (task_id, seq) is a hard backstop.
110	  const seq = runTransaction(() => {
111	    const existing = runQuery(
112	      'SELECT MAX(seq) as seq FROM runtime_events WHERE task_id = ?',
113	      [input.taskId]
114	    )[0] as any;
115	    const nextSeq = Number(existing?.seq || 0) + 1;
116	    runInsert(
117	      `INSERT INTO runtime_events (id, task_id, seq, type, payload, created_at)
118	       VALUES (?, ?, ?, ?, ?, ?)`,
119	      [id, input.taskId, nextSeq, input.type, JSON.stringify(input.payload), now]
120	    );
121	    return nextSeq;
122	  });
123	
124	  const event = { id, taskId: input.taskId, seq, type: input.type, payload: input.payload, createdAt: now };
125	  runtimeEventBus.emit('event', event);
126	  runtimeEventBus.emit(`task:${input.taskId}`, event);
127	  return event;
128	}
