136	export function updateRuntimeTask(id: string, updates: { status?: RuntimeTaskStatus; result?: string; error?: string; metadata?: Record<string, any> }) {
137	  const fields: string[] = [];
138	  const values: any[] = [];
139	  const now = Date.now();
140	
141	  if (updates.status !== undefined) {
142	    fields.push('status = ?');
143	    values.push(updates.status);
144	    if (updates.status === 'running') {
145	      fields.push('started_at = COALESCE(started_at, ?)');
146	      values.push(now);
147	    }
148	    if (updates.status === 'completed' || updates.status === 'failed') {
149	      fields.push('completed_at = ?');
150	      values.push(now);
151	    }
152	    if (updates.status === 'cancelled') {
153	      fields.push('cancelled_at = ?');
154	      values.push(now);
155	      fields.push('completed_at = ?');
156	      values.push(now);
157	    }
158	  }
159	  if (updates.result !== undefined) {
160	    fields.push('result = ?');
161	    values.push(updates.result);
162	  }
163	  if (updates.error !== undefined) {
164	    fields.push('error = ?');
165	    values.push(updates.error);
166	  }
167	  if (updates.metadata !== undefined) {
168	    fields.push('metadata = ?');
169	    values.push(JSON.stringify(updates.metadata));
170	  }
171	
172	  fields.push('updated_at = ?');
173	  values.push(now);
174	  values.push(id);
175	
176	  runExec(`UPDATE runtime_tasks SET ${fields.join(', ')} WHERE id = ?`, values);
177	  return getRuntimeTask(id);
178	}
