21	function buildModelConfig(provider: any, model: any): ModelConfig {
22	  return {
23	    id: `${provider.id}:${model.name}`,
24	    name: model.name,
25	    displayName: model.display_name || model.name,
26	    provider: provider.type === 'openai-compatible' ? 'openai' : provider.type,
27	    apiKey: provider.api_key,
28	    baseUrl: provider.base_url,
29	    maxTokens: model.max_output || 4096,
30	    supportsVision: !!model.supports_vision,
31	    supportsTools: !!model.supports_tools,
32	    costPer1KInput: model.cost_per_1k_input || 0,
33	    costPer1KOutput: model.cost_per_1k_output || 0,
34	    keywords: []
35	  } as ModelConfig;
36	}
