38	function getModelById(modelId: string, userId?: string): { provider: any; model: any } | null {
39	  const parts = modelId.split(':');
40	  if (parts.length < 2) return null;
41	  
42	  const providerId = parts[0];
43	  const modelName = parts.slice(1).join(':');
44	  
45	  let provider: any;
46	  if (userId) {
47	    provider = runQuery('SELECT * FROM model_providers WHERE id = ? AND (user_id = ? OR user_id IS NULL)', [providerId, userId])[0];
48	  } else {
49	    provider = runQuery('SELECT * FROM model_providers WHERE id = ? AND user_id IS NULL', [providerId])[0];
50	  }
51	  
52	  if (!provider) return null;
53	  
54	  const model = runQuery('SELECT * FROM models WHERE provider_id = ? AND name = ? AND enabled = 1', [providerId, modelName])[0];
55	  if (!model) return null;
56	  
57	  return { provider, model };
58	}
