74	function createAgentRuntimeJob(input: {
75	  userId?: string;
76	  prompt: string;
77	  mode: string;
78	  capability: string;
79	  modelId: string;
80	  modelConfig: ModelConfig;
81	  providerId: string;
82	  modelName: string;
83	  workerType?: 'local-agent' | 'container-agent';
84	}) {
85	  const taskId = uuidv4();
86	  const workerType = input.workerType || 'local-agent';
87	  createRuntimeTask({
88	    id: taskId,
89	    userId: input.userId,
90	    kind: 'agent',
91	    prompt: input.prompt,
92	    mode: input.mode,
93	    capability: input.capability,
94	    modelId: input.modelId,
95	    status: 'pending',
96	    metadata: { providerId: input.providerId, modelName: input.modelName, workerType },
97	  });
98	  const workerRunId = createWorkerRun(taskId, workerType, { mode: input.mode, capability: input.capability, modelId: input.modelId }, 'pending');
99	  recordAgentTask(taskId, input.userId, input.prompt, input.mode, input.capability, input.modelId);
100	  runtimeWorkerManager.enqueue({
101	    taskId,
102	    workerRunId,
103	    workerType,
104	    payload: { prompt: input.prompt, mode: input.mode, capability: input.capability, modelConfig: input.modelConfig, modelId: input.modelId },
105	    enqueuedAt: Date.now(),
106	  });
107	  return { taskId, workerRunId };
108	}
