148	function streamRuntimeTask(taskId: string, res: any) {
149	  res.writeHead(200, {
150	    'Content-Type': 'text/event-stream',
151	    'Cache-Control': 'no-cache',
152	    'Connection': 'keep-alive'
153	  });
154	
155	  for (const event of listRuntimeEvents(taskId)) {
156	    writeRuntimeSse(res, event);
157	  }
158	
159	  const unsubscribe = subscribeRuntimeEvents(taskId, event => {
160	    writeRuntimeSse(res, event);
161	    if (event.type === 'task_complete' || event.type === 'task_error' || event.type === 'task_cancelled') {
162	      res.write('data: [DONE]\n\n');
163	      res.end();
164	      unsubscribe();
165	    }
166	  });
167	
168	  res.on('close', () => {
169	    unsubscribe();
170	  });
171	}
