415	router.get('/tasks/:id/events/live', optionalAuth, (req: AuthRequest, res) => {
416	  const taskId = req.params.id;
417	  const afterSeq = Number(req.query.afterSeq || 0);
418	  const task = getRuntimeTaskWithEvents(taskId);
419	
420	  if (!task) {
421	    return res.status(404).json({ success: false, error: 'Task not found' });
422	  }
423	
424	  if (task.userId && req.userId !== task.userId) {
425	    return res.status(403).json({ success: false, error: 'Access denied' });
426	  }
427	
428	  res.writeHead(200, {
429	    'Content-Type': 'text/event-stream',
430	    'Cache-Control': 'no-cache',
431	    'Connection': 'keep-alive'
432	  });
433	
434	  const replayedEvents = listRuntimeEventsAfter(taskId, afterSeq);
435	  for (const event of replayedEvents) {
436	    res.write(`data: ${JSON.stringify({ type: event.type, seq: event.seq, ...event.payload })}\n\n`);
437	  }
438	
439	  const latestTerminalEvent = [...replayedEvents, ...listRuntimeEvents(taskId)]
440	    .reverse()
441	    .find(event => event.type === 'task_complete' || event.type === 'task_error' || event.type === 'task_cancelled');
442	
443	  if (latestTerminalEvent) {
444	    res.write('data: [DONE]\n\n');
445	    res.end();
446	    return;
447	  }
448	
449	  const unsubscribe = subscribeRuntimeEvents(taskId, event => {
450	    res.write(`data: ${JSON.stringify({ type: event.type, seq: event.seq, ...event.payload })}\n\n`);
451	    if (event.type === 'task_complete' || event.type === 'task_error' || event.type === 'task_cancelled') {
452	      res.write('data: [DONE]\n\n');
453	      res.end();
454	      unsubscribe();
455	    }
456	  });
457	
458	  res.on('close', () => unsubscribe());
459	});
