38	
39	  const providerId = parts[0];
40	  const modelName = parts.slice(1).join(':');
41	
42	  let provider: any;
43	  if (userId) {
44	    provider = runQuery('SELECT * FROM model_providers WHERE id = ? AND user_id = ?', [providerId, userId])[0];
45	  } else {
46	    provider = runQuery('SELECT * FROM model_providers WHERE id = ? AND user_id IS NULL', [providerId])[0];
47	  }
48	
49	  if (!provider) return null;
50	
51	  let model: any;
52	  model = runQuery('SELECT * FROM models WHERE provider_id = ? AND name = ? AND enabled = 1', [providerId, modelName])[0];
