70	function extractImageBase64(imageUrl: string): string | null {
71	  const match = imageUrl.match(/^data:image\/(?:png|jpeg|jpg|gif|webp);base64,(.+)$/);
72	  if (match) {
73	    return match[1];
74	  }
75	  return null;
