78	async function processMultimodalMessages(
79	  messages: any[],
80	  modelConfig: ModelConfig,
81	  settings: any
82	): Promise<any[]> {
83	  const visionEnabled = settings?.vision_enabled === 1 || settings?.vision_enabled === true;
84	  const useDedicatedVision = visionEnabled && settings?.vision_api_key && !modelConfig.supportsVision;
85	
86	  if (!useDedicatedVision) {
87	    return messages;
88	  }
89	
90	  const processedMessages: any[] = [];
91	
92	  const { analyzeImage } = await import('../services/multimodal');
93	
94	  for (const msg of messages) {
95	    if (isImageContent(msg.content)) {
96	      let textParts: string[] = [];
97	      const images: string[] = [];
98	
99	      for (const part of msg.content) {
100	        if (part.type === 'text') {
101	          textParts.push(part.text || '');
102	        } else if (part.type === 'image_url') {
103	          const url = part.image_url?.url || '';
104	          const base64 = extractImageBase64(url);
105	          if (base64) {
106	            images.push(base64);
107	          }
108	        }
109	      }
110	
111	      let combinedText = textParts.join('\n');
112	
113	      if (images.length > 0) {
114	        const visionPrompt = combinedText || '请描述这张图片的内容';
115	        try {
116	          const visionResult = await analyzeImage(
117	            settings.vision_api_key,
118	            settings.vision_base_url || 'https://api.stepfun.com/step_plan/v1',
119	            settings.vision_model || 'step-3.7-flash',
120	            images[0],
121	            visionPrompt
122	          );
123	          combinedText = `${combinedText ? combinedText + '\n\n' : ''}[图片识别结果: ${visionResult.content}]`;
124	        } catch (err: any) {
125	          console.error('[Conversations] Vision analysis failed:', err);
126	          combinedText = `${combinedText ? combinedText + '\n\n' : ''}[图片识别失败: ${err.message}]`;
127	        }
128	      }
129	
130	      processedMessages.push({
131	        role: msg.role,
132	        content: combinedText
133	      });
134	    } else {
135	      processedMessages.push(msg);
136	    }
137	  }
138	
139	  return processedMessages;
140	}
