  const alreadyTerminal = history.some(
    event => event.type === 'task_complete' || event.type === 'task_error' || event.type === 'task_cancelled'
  );
  if (alreadyTerminal) {
    res.write('data: [DONE]\n\n');
    res.end();
    return;
  }

  const unsubscribe = subscribeRuntimeEvents(taskId, event => {
    writeRuntimeSse(res, event);
    if (event.type === 'task_complete' || event.type === 'task_error' || event.type === 'task_cancelled') {
      res.write('data: [DONE]\n\n');
      res.end();
      unsubscribe();
    }
  });

  res.on('close', () => {
    unsubscribe();
  });
}
