import { getDatabase, initializeSchema, closeDatabase } from './database'
import fs from 'fs'
import path from 'path'

// 测试脚本：验证 DB 层完整 CRUD
async function testDatabase() {
  const results: string[] = []

  try {
    // 初始化
    initializeSchema()
    const db = getDatabase()
    results.push('✓ Database initialized')

    // 测试 1: 创建对话
    const now = Date.now()
    const convId = `conv_test_${now}`
    db.prepare(`
      INSERT INTO conversations (id, title, model, created_at, updated_at)
      VALUES (?, ?, ?, ?, ?)
    `).run(convId, 'Test Conversation', 'claude-opus-4', now, now)
    results.push('✓ Conversation created')

    // 测试 2: 查询对话
    const conv = db.prepare('SELECT * FROM conversations WHERE id = ?').get(convId) as any
    if (conv && conv.title === 'Test Conversation') {
      results.push('✓ Conversation retrieved')
    } else {
      results.push('✗ Conversation retrieval failed')
    }

    // 测试 3: 插入消息
    const msgId = `msg_test_${now}`
    db.prepare(`
      INSERT INTO messages (id, conversation_id, role, content, created_at)
      VALUES (?, ?, ?, ?, ?)
    `).run(msgId, convId, 'user', 'Hello, world!', now)
    results.push('✓ Message inserted')

    // 测试 4: 查询消息
    const messages = db.prepare('SELECT * FROM messages WHERE conversation_id = ?').all(convId) as any[]
    if (messages.length === 1 && messages[0].content === 'Hello, world!') {
      results.push('✓ Message retrieved')
    } else {
      results.push('✗ Message retrieval failed')
    }

    // 测试 5: 设置读写
    db.prepare("INSERT INTO settings (key, value, updated_at) VALUES ('test_key', ?, ?)")
      .run(JSON.stringify({ foo: 'bar' }), now)
    const setting = db.prepare("SELECT value FROM settings WHERE key = 'test_key'").get() as any
    if (setting && JSON.parse(setting.value).foo === 'bar') {
      results.push('✓ Settings read/write')
    } else {
      results.push('✗ Settings test failed')
    }

    // 测试 6: 级联删除（删除对话应自动删除消息）
    db.prepare('DELETE FROM conversations WHERE id = ?').run(convId)
    const orphanMessages = db.prepare('SELECT * FROM messages WHERE conversation_id = ?').all(convId) as any[]
    if (orphanMessages.length === 0) {
      results.push('✓ Cascade delete works')
    } else {
      results.push('✗ Cascade delete failed')
    }

    // 测试 7: 清理测试数据
    db.prepare("DELETE FROM settings WHERE key = 'test_key'").run()
    results.push('✓ Cleanup complete')

    results.push('\n✅ All database tests passed!')
  } catch (error) {
    results.push(`\n❌ Test failed: ${error}`)
  } finally {
    closeDatabase()
  }

  // 写入结果文件
  const outputPath = path.join(app.getPath('userData'), 'db-test-result.txt')
  fs.writeFileSync(outputPath, results.join('\n'), 'utf-8')

  // 返回退出码
  const success = results[results.length - 1].includes('All database tests passed')
  app.exit(success ? 0 : 1)
}

app.whenReady().then(testDatabase)
