   */
  register<TRequest = any, TResponse = any>(
    channel: string,
    handler: IpcHandler<TRequest, TResponse>
  ): void {
    if (this.handlers.has(channel)) {
      console.warn(`[IPC] Handler for channel "${channel}" already registered, overwriting`)
