    }
  }

  /**
   * 清除所有处理器
   */
  clear(): void {
    for (const channel of this.handlers.keys()) {
      ipcMain.removeHandler(channel)
    }
    this.handlers.clear()
    console.log('[IPC] All handlers cleared')
  }
}

