        const err = error as Error
        console.error(`[IPC] Error in ${channel}:`, err)
        return {
          success: false,
          error: {
            code: 'IPC_ERROR',
            message: err.message,
            stack: err.stack
          }
        }
      }
    }

    this.handlers.set(channel, wrappedHandler as IpcHandler)
    ipcMain.handle(channel, wrappedHandler)
